#!/usr/bin/env python3
"""news-image-20261125 -- one image summing up Wednesday 25 November 2026.

Pure standard library only (base64, os, random, struct, sys, zlib): the
program draws a 1024x1024 newspaper front page and writes it to
$MAKEFUN_OUTPUT_DIR/entry.png (default: ./out/entry.png).

All 46 stories were verified live by the builder on 25 Nov 2026 from the
morning news cycle (Reuters, AP, NYT via Reuters, CNN, RFE/RL, Xinhua,
WHO, WFP and wire roundups dated 25 Nov 2026). Items whose event date was
provably earlier (COP31 collapse on Sun 22 Nov, Champions League results
of Tue 24 Nov, England's T20I win of 24 Nov) were discarded. Lead story:
the CIA and ODNI cyber breach, confirmed by two independent sources
(NYT/Reuters and AP).

Glyph bitmaps in FONT_B64 were generated in-session by the builder's own
script (work-dir gen_font.py) from the system DejaVu fonts; the drawing,
layout, PNG encoder and every headline below were written by hand in this
session. No network is used at run time; output is deterministic.
"""

import base64
import os
import random
import struct
import sys
import zlib

W, H = 1024, 1024
PAPER = (247, 242, 231)
INK = (26, 26, 26)
RED = (155, 27, 27)
GREY = (80, 76, 68)
RULEC = (170, 158, 138)
GRAIN_AMP = 1          # print-grain amplitude, tuned so the PNG lands 450-600 KB
GRAIN_SEED = 20261125

# Glyph bitmaps (REG12, BOLD12, BOLD32) packed by gen_font.py; see module docstring.
FONT_B64 = (
    "")


# ---------------------------------------------------------------- fonts
def _load_fonts(blob):
    """Parse the packed blob into {name: {char: (adv, pixels)}}.

    pixels is a list of (dx, dy, coverage) triples, coverage 0..255,
    relative to the glyph's anchor point (ascender top, left edge).
    """
    fonts = {}
    pos = 0
    while pos < len(blob):
        name = blob[pos:pos + 6].decode("ascii").strip()
        pos += 6
        (nbytes,) = struct.unpack_from("<H", blob, pos)
        pos += 2
        data = blob[pos:pos + nbytes]
        pos += nbytes
        glyphs = {}
        p = 0
        while p < len(data):
            code, adv, w, h, xoff, yoff = struct.unpack_from("BBBBbb", data, p)
            p += 6
            pix = []
            for gy in range(h):
                row = data[p + gy * w:p + (gy + 1) * w]
                for gx, cov in enumerate(row):
                    if cov:
                        pix.append((xoff + gx, yoff + gy, cov))
            p += w * h
            glyphs[chr(code)] = (adv, pix)
        fonts[name] = glyphs
    return fonts


def _downscale(font, factor=2):
    """Derive a half-size font by averaging factor x factor blocks."""
    out = {}
    for ch, (adv, pix) in font.items():
        # rebuild a dense grid, then average blocks
        if not pix:
            out[ch] = (max(1, adv // factor), [])
            continue
        maxx = max(dx for dx, _, _ in pix)
        maxy = max(dy for _, dy, _ in pix)
        minx = min(dx for dx, _, _ in pix)
        miny = min(dy for _, dy, _ in pix)
        gw = maxx - minx + 1
        gh = maxy - miny + 1
        grid = [[0] * gw for _ in range(gh)]
        for dx, dy, cov in pix:
            grid[dy - miny][dx - minx] = cov
        nw = (gw + factor - 1) // factor
        nh = (gh + factor - 1) // factor
        npix = []
        for by in range(nh):
            for bx in range(nw):
                s = 0
                n = 0
                for yy in range(by * factor, min((by + 1) * factor, gh)):
                    for xx in range(bx * factor, min((bx + 1) * factor, gw)):
                        s += grid[yy][xx]
                        n += 1
                cov = s // n
                if cov:
                    npix.append((minx // factor + bx, miny // factor + by, cov))
        out[ch] = (max(1, adv // factor), npix)
    return out


FONTS = _load_fonts(base64.b64decode(FONT_B64))
FONTS["BOLD16"] = _downscale(FONTS["BOLD32"])


def text_width(font, s, tracking=0):
    w = 0
    for ch in s:
        g = font.get(ch)
        w += (g[0] if g else 8) + tracking
    return w - tracking if s else 0


def wrap(font, text, maxw):
    """Greedy word wrap; returns a list of lines (each fits maxw)."""
    lines = []
    for para in text.split("\n"):
        words = para.split(" ")
        cur = ""
        for word in words:
            trial = (cur + " " + word).strip()
            if text_width(font, trial) <= maxw or not cur:
                cur = trial
            else:
                lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
    return lines


# ---------------------------------------------------------------- canvas
class Canvas:
    def __init__(self):
        self.buf = bytearray(PAPER[0:1] * 0)  # placeholder, replaced below
        self.buf = bytearray(W * H * 3)
        for i in range(W * H):
            j = i * 3
            self.buf[j] = PAPER[0]
            self.buf[j + 1] = PAPER[1]
            self.buf[j + 2] = PAPER[2]

    def rect(self, x, y, w, h, color):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(W, x + w)
        y1 = min(H, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(color) * (x1 - x0)
        for yy in range(y0, y1):
            off = (yy * W + x0) * 3
            self.buf[off:off + len(row)] = row

    def hline(self, x, y, w, color, thick=1):
        self.rect(x, y, w, thick, color)

    def pixel(self, x, y, color):
        if 0 <= x < W and 0 <= y < H:
            j = (y * W + x) * 3
            self.buf[j] = color[0]
            self.buf[j + 1] = color[1]
            self.buf[j + 2] = color[2]

    def text(self, font, x, y, s, color, tracking=0):
        cx = x
        for ch in s:
            g = font.get(ch)
            if g is None:
                cx += 8 + tracking
                continue
            adv, pix = g
            for dx, dy, cov in pix:
                px = cx + dx
                py = y + dy
                if 0 <= px < W and 0 <= py < H:
                    j = (py * W + px) * 3
                    inv = 255 - cov
                    self.buf[j] = (color[0] * cov + self.buf[j] * inv) // 255
                    self.buf[j + 1] = (color[1] * cov + self.buf[j + 1] * inv) // 255
                    self.buf[j + 2] = (color[2] * cov + self.buf[j + 2] * inv) // 255
            cx += adv + tracking

    def text_center(self, font, y, s, color, tracking=0):
        self.text(font, (W - text_width(font, s, tracking)) // 2, y, s, color, tracking)

    def circle(self, cx, cy, r, color):
        # parametric outline, 1-degree steps
        import math
        for deg in range(360):
            a = math.radians(deg)
            self.pixel(cx + int(round(r * math.cos(a))),
                       cy + int(round(r * math.sin(a))), color)

    def ellipse(self, cx, cy, rx, ry, color, a0=0, a1=360):
        import math
        for deg in range(a0, a1 + 1):
            a = math.radians(deg)
            self.pixel(cx + int(round(rx * math.cos(a))),
                       cy + int(round(ry * math.sin(a))), color)

    def grain(self):
        rnd = random.Random(GRAIN_SEED)
        noise = rnd.randbytes(W * H)
        amp = GRAIN_AMP
        buf = self.buf
        for i in range(W * H):
            d = (noise[i] % (2 * amp + 1)) - amp
            if d:
                j = i * 3
                v = buf[j] + d
                buf[j] = 0 if v < 0 else (255 if v > 255 else v)
                v = buf[j + 1] + d
                buf[j + 1] = 0 if v < 0 else (255 if v > 255 else v)
                v = buf[j + 2] + d
                buf[j + 2] = 0 if v < 0 else (255 if v > 255 else v)

    def png_bytes(self):
        raw = bytearray()
        stride = W * 3
        for y in range(H):
            raw.append(0)
            raw += self.buf[y * stride:(y + 1) * stride]
        comp = zlib.compress(bytes(raw), 9)

        def chunk(typ, data):
            c = struct.pack(">I", len(data)) + typ + data
            c += struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)
            return c

        ihdr = struct.pack(">IIBBBBB", W, H, 8, 2, 0, 0, 0)
        return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", ihdr)
                + chunk(b"IDAT", comp) + chunk(b"IEND", b""))


