LEAD_KICKER = "LEAD STORY - UNITED STATES"
LEAD_HEAD = ["CIA AND SPY CHIEF'S OFFICE", "HIT BY CYBER BREACH"]
LEAD_SUB = (
    "The CIA and the Office of the Director of National Intelligence discovered "
    "a breach that exposed some unclassified information, the New York Times "
    "reported. The Associated Press confirmed no classified data was involved, "
    "and ODNI said there were no disruptions to critical systems. "
    "Who carried out the attack is not known.")
LEAD_CHIPS = ["UNCLASSIFIED DATA EXPOSED", "NO CLASSIFIED SYSTEMS HIT",
              "ATTACKER UNKNOWN"]


# ---------------------------------------------------------------- layout
COL_X = [24, 354, 684]
COL_W = 314
COL_SECTIONS = [[0, 1], [2, 3], [4, 5, 6, 7]]
BODY_TOP = 306
BODY_BOTTOM = 962


def draw_column(cv, x, section_ids, col_no):
    """Draw one column; returns the y just below its last item."""
    y = BODY_TOP
    reg = FONTS["REG12"]
    bold = FONTS["BOLD12"]
    head = FONTS["BOLD16"]
    for si in section_ids:
        name, items = SECTIONS[si]
        cv.text(head, x, y, name, RED)
        y += 20
        cv.hline(x, y, COL_W, INK, 2)
        y += 8
        for hl, sub in items:
            if text_width(bold, hl) > COL_W:
                print("WARN headline too wide (%d): %s"
                      % (text_width(bold, hl), hl), file=sys.stderr)
            cv.text(bold, x, y, hl, INK)
            y += 15
            for line in wrap(reg, sub, COL_W):
                cv.text(reg, x, y, line, GREY)
                y += 14
            y += 4
        y += 2
    return y


def draw(cv):
    bold12 = FONTS["BOLD12"]
    reg12 = FONTS["REG12"]
    bold32 = FONTS["BOLD32"]

    # --- masthead
    cv.text_center(bold12, 26, "THE WORLD IN ONE DAY  |  GLOBAL EDITION", RED, tracking=2)
    cv.text_center(bold32, 46, "WEDNESDAY, 25 NOVEMBER 2026", INK)
    cv.hline(24, 92, W - 48, INK, 1)
    cv.hline(24, 96, W - 48, INK, 3)

    # --- lead band
    cv.text(bold12, 24, 110, LEAD_KICKER, RED, tracking=1)
    y = 128
    for line in LEAD_HEAD:
        cv.text(bold32, 24, y, line, INK)
        y += 38
    y += 6
    for line in wrap(reg12, LEAD_SUB, 700):
        cv.text(reg12, 24, y, line, GREY)
        y += 15
    y += 8
    cx = 24
    for chip in LEAD_CHIPS:
        wch = text_width(bold12, chip) + 18
        cv.hline(cx, y, wch, INK, 1)
        cv.hline(cx, y + 22, wch, INK, 1)
        cv.rect(cx, y, 1, 23, INK)
        cv.rect(cx + wch - 1, y, 1, 23, INK)
        cv.text(bold12, cx + 9, y + 6, chip, INK)
        cx += wch + 10
    # globe motif, right of the lead
    gx, gy, gr = 888, 200, 76
    cv.circle(gx, gy, gr, INK)
    cv.ellipse(gx, gy, 34, gr, INK)
    cv.ellipse(gx, gy, gr, 30, INK)
    cv.ellipse(gx, gy, gr, 30, INK, a0=200, a1=340)
    cv.hline(gx - gr, gy, 2 * gr, INK, 1)
    for rr in range(1, 7):
        cv.circle(gx, gy, rr, RED)

    # --- body: three dense columns
    cv.hline(24, 298, W - 48, INK, 3)
    bottoms = []
    for i, secs in enumerate(COL_SECTIONS):
        bottoms.append(draw_column(cv, COL_X[i], secs, i))
    for b in bottoms:
        if b > BODY_BOTTOM:
            print("WARN column overflows by %d px" % (b - BODY_BOTTOM),
                  file=sys.stderr)

    # --- footer
    cv.hline(24, 972, W - 48, INK, 1)
    cv.text_center(reg12, 982,
                   "ALL EVENTS OF WEDNESDAY 25 NOVEMBER 2026 - FIRST REPORTED THAT DAY",
                   GREY)
    cv.text_center(reg12, 998,
                   "SOURCES: REUTERS, AP, NYT, CNN, RFE/RL, XINHUA, WHO, WFP  |  PAGE 1",
                   GREY)


def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR", "out")
    os.makedirs(outdir, exist_ok=True)
    cv = Canvas()
    draw(cv)
    cv.grain()
    data = cv.png_bytes()
    path = os.path.join(outdir, "entry.png")
    with open(path, "wb") as f:
        f.write(data)
    print("wrote %s (%d bytes)" % (path, len(data)))


if __name__ == "__main__":
    main()
